import java.util.List;

public class Main {

    enum Prop { REQUIRED, REQUIRES_NEW, NESTED, SUPPORTS, NOT_SUPPORTED, MANDATORY, NEVER }

    static class Tx {
        final int id;
        final java.util.List<String> ops = new java.util.ArrayList<>();
        final java.util.List<Integer> savepoints = new java.util.ArrayList<>();
        Tx(int id) { this.id = id; }
    }

    static class TxManager {
        final java.util.List<String> db = new java.util.ArrayList<>();
        int seq = 0;
        Tx current = null;

        Tx begin(Prop p) {
            switch (p) {
                case REQUIRED:
                    if (current != null) return current;
                    current = new Tx(++seq);
                    return current;
                case REQUIRES_NEW: {
                    current = new Tx(++seq);
                    return current;
                }
                case NESTED:
                    if (current != null) {
                        current.savepoints.add(current.ops.size());
                        System.out.println("savepoint sp" + current.savepoints.size()
                                + " at depth " + current.ops.size());
                        return current;
                    }
                    current = new Tx(++seq);
                    return current;
                case SUPPORTS:
                    return current;
                case NOT_SUPPORTED:
                    current = null;
                    return null;
                case MANDATORY:
                    if (current == null)
                        throw new IllegalStateException("No existing transaction found for MANDATORY");
                    return current;
                case NEVER:
                    if (current != null)
                        throw new IllegalStateException("Existing transaction found for NEVER");
                    return null;
                default:
                    return current;
            }
        }

        void op(String s) {
            if (current != null) current.ops.add(s);
            else db.add(s);
        }

        void commit(Tx t) {
            if (t == null) return;
            db.addAll(t.ops);
            if (current == t) current = null;
        }

        void rollback(Tx t) {
            if (current == t) current = null;
        }

        void rollbackToSavepoint(Tx t) {
            if (t == null || t.savepoints.isEmpty()) return;
            int mark = t.savepoints.remove(t.savepoints.size() - 1);
            while (t.ops.size() > mark) t.ops.remove(t.ops.size() - 1);
        }
    }

    static class ReadOnlyTx {
        boolean readOnly; final java.util.List<String> ops = new java.util.ArrayList<>();
        ReadOnlyTx(boolean ro) { this.readOnly = ro; }
        void write(String s) {
            if (readOnly)
                throw new IllegalStateException("Write operations are not allowed in read-only transaction");
            ops.add(s);
        }
    }

    public static void main(String[] args) {
        ReadOnlyTx ro = new ReadOnlyTx(true);
        boolean rejected = false;
        try { ro.write("insert:order"); }
        catch (IllegalStateException e) { rejected = true; }
        System.out.println("[A] readOnly tx rejected write: " + rejected);
        System.out.println("[A] nothing persisted, ops=" + ro.ops);

        int timeoutOps = 3;
        TxManager tm = new TxManager();
        Tx tx = tm.begin(Prop.REQUIRED);
        for (int i = 1; i <= 4; i++) tm.op("op" + i);
        boolean exceeded = tx.ops.size() > timeoutOps;
        System.out.println("[B] tx ops=" + tx.ops.size() + " > timeoutOps=" + timeoutOps
                + " exceeded: " + exceeded);
        if (exceeded) tm.rollback(tx);
        System.out.println("[B] timed out -> rolled back, db=" + tm.db);
    }
}
